/**
 * Artifact envelope for every view in this app.
 *
 * Each view renders `frontend/public/artifacts/<key>.json`, generated by
 * `danon/app_artifacts.py` from a real engine run. The envelope carries the
 * exact call that produced it, the modelling-providence map, and the
 * limitations, so a view can always state where its numbers came from and
 * what they are not.
 */

import type { PipelineResult } from './index';

export interface AppArtifact<T> {
  key: string;
  title: string;
  generated_utc: string;
  source: string;
  notes: string[];
  provenance: Record<string, string>;
  data: T;
}

/* --------------------------------------------------------------- claims -- */

/** One published sentence, the check that backs it, and whether it passes. */
export interface ClaimRow {
  id: string;
  sentence: string;
  tier: string;
  substantiated_by: string;
  check: string;
  limit: string;
  supported: boolean;
  detail: string;
}

export interface ClaimsArtifactData {
  n_claims: number;
  n_passed: number;
  n_failed: number;
  claims: ClaimRow[];
  provenance: Record<string, string>;
  cannot_establish: string[];
}

/* ------------------------------------------------------------- pipeline -- */

export interface PipelineArtifactData extends PipelineResult {
  constraints: Record<string, number>;
}

/* -------------------------------------------------------- microfluidics -- */

export interface MicrofluidicConfigData {
  channel_height_um: number;
  channel_width_um: number;
  inlet_angle_deg: number;
  aqueous_flow_rate_ul_min: number;
  organic_flow_rate_ul_min: number;
  aqueous_density_kg_m3: number;
  organic_density_kg_m3: number;
  aqueous_viscosity_pa_s: number;
  organic_viscosity_pa_s: number;
  diff_coefficient_m2_s: number;
  channel_length_mm: number;
  surface_roughness_um: number;
}

export interface MicrofluidicTelemetryData {
  reynolds_number_aqueous: number;
  reynolds_number_organic: number;
  reynolds_number_mixed: number;
  wall_shear_stress_pa: number;
  max_shear_stress_pa: number;
  mixing_efficiency: number;
  peclet_number: number;
  deans_number: number;
  pressure_drop_pa: number;
  flow_regime: string;
  shear_stress_safe: boolean;
  frr: number;
  hydraulic_diameter_um: number;
}

export interface MicrofluidicsArtifactData {
  config: MicrofluidicConfigData;
  telemetry: MicrofluidicTelemetryData;
  velocity_profile: { positions_um: number[]; velocities_m_s: number[] };
  concentration_profile: number[];
  hydraulic_diameter_um: number;
  flow_rate_ratio: number;
}

/* ------------------------------------------------------------------ lnp -- */

export interface LipidBand {
  name: string;
  role: string;
  color: string;
  frac: number;
}

export interface LNPCandidateData {
  candidate_id: number;
  ionizable_lipid: string;
  peg_lipid: string;
  helper_lipid: string;
  ionizable_frac: number;
  peg_frac: number;
  helper_frac: number;
  cholesterol_frac: number;
  tail_length: number;
  unsaturation: number;
  pka: number;
  cardiac_delivery_score: number;
  hepatic_avoidance_score: number;
  endosomal_escape_score: number;
  immune_activation: number;
  particle_size_nm: number;
  fitness: number;
}

export interface LNPArtifactData {
  best: LNPCandidateData;
  top_candidates: LNPCandidateData[];
  composition: LipidBand[];
  summary: {
    n_candidates: number;
    mean_size_nm: number;
    sd_size_nm: number;
    mean_fitness: number;
    best_fitness: number;
    worst_fitness: number;
    size_range_nm: [number, number];
  };
  ionizable_lipids_seen: string[];
  peg_lipids_seen: string[];
}

/* ------------------------------------------------------------- clinical -- */

export interface DoseResponseRow {
  vector_copy_number: number;
  lamp2b_restoration_pct: number;
  glycogen_clearance_pct: number;
  autophagic_flux: number;
  functional_cure_score: number;
  is_cure: boolean;
  survival_5y: number;
}

export interface MutationRow {
  mutation: string;
  lamp2_pct: number;
  glycogen_clearance_pct: number;
  flux_restoration_pct: number;
  cure_score: number;
  is_cure: boolean;
  survival_10y: number;
}

export interface ClinicalArtifactData {
  dose_response: DoseResponseRow[];
  mutation_comparison: MutationRow[];
  vector_copy_number: number;
  benchmark: Record<string, number | { error: string }>;
}

/* ------------------------------------------------------------ structure -- */
export interface StructureResidue {
  vp1: number;
  stored: number;
  aa: string;
  x: number;
  y: number;
  z: number;
  radius_a: number;
  contacts: number;
  exposure_proxy: number;
}

export interface SymmetryOperator {
  index: number;
  order: number;
  angle_deg: number;
  axis: number[] | null;
  rotation: number[][];
  translation: number[];
}

export interface StructureArtifactData {
  structure_id: string;
  title: string;
  method: string;
  reference: string;
  sha256: string | null;
  mislabeled_prior_id: string;
  mislabeled_prior_id_actual: string;
  geometry: {
    subunits: number;
    ca_atoms: number;
    asymmetric_unit_residues: number;
    centre: [number, number, number];
    inner_radius_a: number;
    mean_radius_a: number;
    outer_radius_a: number;
    protrusions: number;
    three_fold_axis_lines: number;
    five_fold_axis_lines: number;
    two_fold_axis_lines: number;
  };
  asymmetric_unit: StructureResidue[];
  symmetry_operators: SymmetryOperator[];
  axes: Record<string, { lines: number[][]; line_count: number }>;
  vr_regions: Record<
    string,
    {
      vp1_range: [number, number];
      stored_range: [number, number];
      residues: {
        vp1: number;
        stored: number;
        aa: string;
        x: number;
        y: number;
        z: number;
        exposure_proxy: number;
      }[];
    }
  >;
}

/* ------------------------------------------------------------ construct -- */

export interface ConstructSegment {
  id: string;
  label: string;
  start_bp: number;
  end_bp: number;
  length_bp: number;
  color: string;
  desc: string;
  start_frac: number;
  end_frac: number;
}

export interface ConstructArtifactData {
  name: string;
  promoter_name: string;
  segments: ConstructSegment[];
  total_length_bp: number;
  cargo_length_bp: number;
  packaging_limit_bp: number;
  has_mirna_detarget: boolean;
  synthesis_vendor: string;
  synthesis_cost_usd: number;
  segment_bp_sum: number;
  sequence_length_bp: number;
}

/* ------------------------------------------------------------- paraview -- */

export interface FieldStats {
  min: number;
  max: number;
  mean_in_tumour: number;
}

/* ------------------------------------------------------------- evolution -- */

/** One arm's frame series + the daily curves the timeline syncs to. */
export interface EvolutionArmData {
  arm: 'policy' | 'mtd';
  seed: number;
  frame_days: number[];
  frames_vti_b64: string[];
  burden_S: number[];
  burden_R: number[];
  dose_A: number[];
  dose_B: number[];
  pfs_day: number | null;
  progressed: boolean;
  toxicity: number;
  grid: [number, number, number];
  spacing_mm: number;
  r0: number;
  days: number;
  pfs_note: string;
}

export interface EvolutionArtifactData {
  generated_utc: string;
  model: string;
  seed: number;
  r0: number;
  days: number;
  grid: [number, number, number];
  spacing_mm: number;
  frame_days: number[];
  arms: { policy: EvolutionArmData; mtd: EvolutionArmData };
  resistant_fraction: { policy: number[]; mtd: number[] };
  static_maps?: Record<string, string>;
  notes: string[];
  case_id: string;
  r0_source: string;
  geometry_note: string;
  budget: {
    days: number;
    dense_until: number;
    max_frames: number;
    frames_per_arm: number;
  };
}

export interface ParaviewArtifactData {
  vti_base64: string;
  vti_sha256: string;
  vti_size_bytes: number;
  grid: {
    dims: [number, number, number];
    spacing_mm: number;
    n_points: number;
    tumour_voxels: number;
  };
  field_stats: Record<string, FieldStats>;
  tissue_counts: Record<string, number>;
  headline: {
    resistant_fraction: number;
    resistant_fraction_note: string;
    diffusion_contrast_ratio: number;
  };
  arrays_present: string[];
  captions: { short: string };
  paraview_recipe: string[];
}
